public struct Document: OmniBufMessage, Equatable, Sendable {
    public var id: String
    public var status: Int32
    public var meta: DocumentMeta?
    public var items: [DocumentItem]

    public init(
        id: String = "",
        status: Int32 = 0,
        meta: DocumentMeta? = nil,
        items: [DocumentItem] = []
    ) {
        self.id = id
        self.status = status
        self.meta = meta
        self.items = items
    }

    public init() {
        self.init(id: "")
    }

    @inlinable
    public var estimatedOmniBufSize: Int {
        estimatedOmniBufSize(depth: 0)
    }

    @inlinable
    public func estimatedOmniBufSize(depth: Int) -> Int {
        var n = 16
        n &+= id.utf8.count
        if let m = meta, depth < WireType.maxNestingDepth { n &+= m.estimatedOmniBufSize(depth: depth &+ 1) &+ 4 }
        if depth < WireType.maxNestingDepth {
            for m in items { n &+= m.estimatedOmniBufSize(depth: depth &+ 1) &+ 4 }
        } else {
            n &+= items.count &* 16
        }
        return n
    }

    @inlinable
    public func marshalOmniBuf() throws -> [UInt8] {
        var w = OmniBufWriter(initialCapacity: max(256, estimatedOmniBufSize))
        try encodeOmniBufBodyFast(into: &w, deterministic: true, depth: 0)
        return w.toBytes()
    }

    @inlinable
    public func encodeOmniBufBody(into writer: inout OmniBufWriter, options: EncodeOptions) throws {
        try encodeOmniBufBodyFast(into: &writer, deterministic: options.deterministic, depth: 0)
    }

    @inlinable
    public func encodeOmniBufBodyFast(into w: inout OmniBufWriter, deterministic: Bool, depth: Int = 0) throws {
        guard depth <= WireType.maxNestingDepth else {
            throw OmniBufError.depthLimitExceeded(depth)
        }
        if !self.id.isEmpty {
            w.appendTag(fieldNumber: 1, wireType: WireType.wireString)
            w.appendStringValue(self.id)
        }
        if self.status != 0 {
            w.appendTag(fieldNumber: 2, wireType: WireType.wireSint)
            w.appendZigZag32(self.status)
        }
        if let sub = self.meta {
            let nextDepth = depth &+ 1
            guard nextDepth <= WireType.maxNestingDepth else { throw OmniBufError.depthLimitExceeded(nextDepth) }
            w.appendTag(fieldNumber: 3, wireType: WireType.wireSubMsg)
            let lenPos = w.reserveLength2()
            try sub.encodeOmniBufBodyFast(into: &w, deterministic: deterministic, depth: nextDepth)
            w.backpatchLength2(at: lenPos)
        }
        if !self.items.isEmpty {
            let arrDepth = depth &+ 1
            guard arrDepth <= WireType.maxNestingDepth else { throw OmniBufError.depthLimitExceeded(arrDepth) }
            let elemDepth = arrDepth &+ 1
            guard elemDepth <= WireType.maxNestingDepth else { throw OmniBufError.depthLimitExceeded(elemDepth) }
            w.appendTag(fieldNumber: 4, wireType: WireType.wireArray)
            let lenPos = w.reserveLength2()
            w.appendByte(WireType.wireSubMsg)
            w.appendVarint(UInt64(self.items.count))
            for elem in self.items {
                let elemLenPos = w.reserveLength2()
                try elem.encodeOmniBufBodyFast(into: &w, deterministic: deterministic, depth: elemDepth)
                w.backpatchLength2(at: elemLenPos)
            }
            w.backpatchLength2(at: lenPos)
        }
    }

    @inlinable
    public mutating func mergeOmniBuf(from data: UnsafeBufferPointer<UInt8>, depth: Int, budget: inout DecodeBudget) throws {
        guard depth <= budget.maxDepth else {
            throw OmniBufError.depthLimitExceeded(depth)
        }
        var r = OmniBufReader(data)
        while !r.isAtEnd {
            let (fnum, wt) = try r.readTag()
            switch fnum {
            case 0:
                guard wt == WireType.wireSubMsg else {
                    throw OmniBufError.parse("Field #0 must have WireSubMsg (12), got \(wt)")
                }
                let slice = try r.readLenSlice()
                try SchemaMeta.validateSlice(slice, depth: depth &+ 1, budget: &budget)
            case 1:
                guard wt == WireType.wireString else {
                    try r.validateValue(wireType: wt, inCollection: false, depth: depth, maxDepth: budget.maxDepth)
                    continue
                }
                self.id = try r.readString(budget: &budget)
            case 2:
                guard wt == WireType.wireSint else {
                    try r.validateValue(wireType: wt, inCollection: false, depth: depth, maxDepth: budget.maxDepth)
                    continue
                }
                self.status = try r.readSint32()
            case 3:
                guard wt == WireType.wireSubMsg else {
                    try r.validateValue(wireType: wt, inCollection: false, depth: depth, maxDepth: budget.maxDepth)
                    continue
                }
                let nextDepth = depth &+ 1
                guard nextDepth <= budget.maxDepth else { throw OmniBufError.depthLimitExceeded(nextDepth) }
                let slice = try r.readLenSlice()
                var sub = self.meta ?? DocumentMeta()
                try sub.mergeOmniBuf(from: slice, depth: nextDepth, budget: &budget)
                self.meta = sub
            case 4:
                guard wt == WireType.wireArray else {
                    try r.validateValue(wireType: wt, inCollection: false, depth: depth, maxDepth: budget.maxDepth)
                    continue
                }
                let arrDepth = depth &+ 1
                guard arrDepth <= budget.maxDepth else { throw OmniBufError.depthLimitExceeded(arrDepth) }
                let body = try r.readLenSlice(minLen: 2)
                let (elemWT, count, er0) = try OmniBufReader.parseArrayBody(body)
                guard elemWT == WireType.wireSubMsg else {
                    throw OmniBufError.parse("field 4 array element type mismatch")
                }
                try budget.addElements(count)
                try budget.addAlloc(count: count, elementBytes: max(MemoryLayout<DocumentItem>.stride, 16))
                let (newCap, capOverflow) = self.items.count.addingReportingOverflow(count)
                if capOverflow { throw OmniBufError.allocationLimitExceeded("array capacity overflow") }
                var er = er0
                self.items.reserveCapacity(newCap)
                for _ in 0..<count {
                    let elemDepth = arrDepth &+ 1
                    guard elemDepth <= budget.maxDepth else { throw OmniBufError.depthLimitExceeded(elemDepth) }
                    let slice = try er.readLenSlice()
                    var elem = DocumentItem()
                    try elem.mergeOmniBuf(from: slice, depth: elemDepth, budget: &budget)
                    self.items.append(elem)
                }
                guard er.isAtEnd else { throw OmniBufError.parse("WireArray trailing bytes") }
            default:
                try r.validateValue(wireType: wt, inCollection: false, depth: depth, maxDepth: budget.maxDepth)
            }
        }
    }

    public static var omniBufSchemaMeta: SchemaMeta {
        var visited: Set<String> = []
        return buildOmniBufSchemaMeta(visited: &visited)
    }

    public static func buildOmniBufSchemaMeta(visited: inout Set<String>) -> SchemaMeta {
        var fields: [UInt32: String] = [:]
        var children: [UInt32: SchemaMeta] = [:]
        let typeKey = "benchmark.v2.Document"
        let inserted = visited.insert(typeKey).inserted
        defer { if inserted { visited.remove(typeKey) } }
        fields[1] = "id"
        fields[2] = "status"
        fields[3] = "meta"
        if inserted { children[3] = DocumentMeta.buildOmniBufSchemaMeta(visited: &visited) }
        fields[4] = "items"
        if inserted { children[4] = DocumentItem.buildOmniBufSchemaMeta(visited: &visited) }
        return SchemaMeta(typeName: "Document", fields: fields, children: children)
    }
}

