public struct OpaqueBatchDocument: Sendable {
    public let raw: [UInt8]
    public let offset: Int
    public let length: Int
    @usableFromInline internal var dirtyMask: UInt64 = 0
    @usableFromInline internal var dirty_items: [Document] = []

    @inlinable
    public init(_ raw: [UInt8]) {
        self.raw = raw
        self.offset = 0
        self.length = raw.count
    }

    @inlinable
    public init(raw: [UInt8], offset: Int, length: Int) {
        precondition(offset >= 0 && length >= 0 && offset <= raw.count && length <= raw.count - offset, "OpaqueBatchDocument slice out of bounds")
        self.raw = raw
        self.offset = offset
        self.length = length
    }

    @inlinable
    @inline(__always)
    internal func withSlice<R>(_ body: (UnsafeBufferPointer<UInt8>) -> R) -> R {
        raw.withUnsafeBufferPointer { buf in
            body(UnsafeBufferPointer(start: buf.baseAddress?.advanced(by: offset), count: length))
        }
    }

    @inlinable
    public var itemsCount: Int {
        if (dirtyMask & (1 &<< 1)) != 0 { return dirty_items.count }
        return withSlice { OpaqueWire.arrayCount(in: $0, fieldNumber: 1, expectedElemType: WireType.wireSubMsg) }
    }
    @inlinable
    public mutating func setItems(_ value: [Document]) {
        dirty_items = value
        dirtyMask |= (1 &<< 1)
    }

    @inlinable
    internal func appendDirtyField(_ fnum: UInt32, into w: inout OmniBufWriter) throws {
        let depth = 0
        _ = depth
        switch fnum {
        case 1:
            if !self.dirty_items.isEmpty {
                let arrDepth = depth &+ 1
                guard arrDepth <= WireType.maxNestingDepth else { throw OmniBufError.depthLimitExceeded(arrDepth) }
                let elemDepth = arrDepth &+ 1
                guard elemDepth <= WireType.maxNestingDepth else { throw OmniBufError.depthLimitExceeded(elemDepth) }
                w.appendTag(fieldNumber: 1, wireType: WireType.wireArray)
                let lenPos = w.reserveLength2()
                w.appendByte(WireType.wireSubMsg)
                w.appendVarint(UInt64(self.dirty_items.count))
                for elem in self.dirty_items {
                    let elemLenPos = w.reserveLength2()
                    try elem.encodeOmniBufBodyFast(into: &w, deterministic: true, depth: elemDepth)
                    w.backpatchLength2(at: elemLenPos)
                }
                w.backpatchLength2(at: lenPos)
            }
        default:
            break
        }
    }

    @inlinable
    public func marshal() -> [UInt8] {
        if dirtyMask == 0 {
            if offset == 0 && length == raw.count { return raw }
            return Array(raw[offset..<(offset + length)])
        }
        var dst: [UInt8] = []
        OpaqueWire.spliceFields(into: &dst, raw: raw, offset: offset, length: length, dirtyMask: dirtyMask, maxField: 1) { w, fnum in
            try? self.appendDirtyField(fnum, into: &w)
        }
        return dst
    }

    @inlinable
    public func tryMarshal() throws -> [UInt8] {
        var dst: [UInt8] = []
        try OpaqueWire.trySpliceFields(into: &dst, raw: raw, offset: offset, length: length, dirtyMask: dirtyMask, maxField: 1) { w, fnum in
            try self.appendDirtyField(fnum, into: &w)
        }
        return dst
    }
}

public struct Telemetry: OmniBufMessage, Equatable, Sendable {
    public var source: String
    public var ts: Int64
    public var tags: [String]
    public var values: [Double]

    public init(
        source: String = "",
        ts: Int64 = 0,
        tags: [String] = [],
        values: [Double] = []
    ) {
        self.source = source
        self.ts = ts
        self.tags = tags
        self.values = values
    }

    public init() {
        self.init(source: "")
    }

    @inlinable
    public var estimatedOmniBufSize: Int {
        estimatedOmniBufSize(depth: 0)
    }

    @inlinable
    public func estimatedOmniBufSize(depth: Int) -> Int {
        var n = 16
        n &+= source.utf8.count
        for s in tags { n &+= s.utf8.count &+ 4 }
        n &+= values.count &* 8
        return n
    }

    @inlinable
    public func marshalOmniBuf() throws -> [UInt8] {
        var w = OmniBufWriter(initialCapacity: max(256, estimatedOmniBufSize))
        try encodeOmniBufBodyFast(into: &w, deterministic: true, depth: 0)
        return w.toBytes()
    }

    @inlinable
    public func encodeOmniBufBody(into writer: inout OmniBufWriter, options: EncodeOptions) throws {
        try encodeOmniBufBodyFast(into: &writer, deterministic: options.deterministic, depth: 0)
    }

    @inlinable
    public func encodeOmniBufBodyFast(into w: inout OmniBufWriter, deterministic: Bool, depth: Int = 0) throws {
        guard depth <= WireType.maxNestingDepth else {
            throw OmniBufError.depthLimitExceeded(depth)
        }
        if !self.source.isEmpty {
            w.appendTag(fieldNumber: 1, wireType: WireType.wireString)
            w.appendStringValue(self.source)
        }
        if self.ts != 0 {
            w.appendTag(fieldNumber: 2, wireType: WireType.wireSint)
            w.appendZigZag(self.ts)
        }
        if !self.tags.isEmpty {
            let arrDepth = depth &+ 1
            guard arrDepth <= WireType.maxNestingDepth else { throw OmniBufError.depthLimitExceeded(arrDepth) }
            w.appendTag(fieldNumber: 3, wireType: WireType.wireArray)
            let lenPos = w.reserveLength2()
            w.appendByte(WireType.wireString)
            w.appendVarint(UInt64(self.tags.count))
            for elem in self.tags {
                w.appendStringValue(elem)
            }
            w.backpatchLength2(at: lenPos)
        }
        if !self.values.isEmpty {
            let arrDepth = depth &+ 1
            guard arrDepth <= WireType.maxNestingDepth else { throw OmniBufError.depthLimitExceeded(arrDepth) }
            w.appendTag(fieldNumber: 4, wireType: WireType.wireArray)
            let lenPos = w.reserveLength2()
            w.appendByte(WireType.wireFloat64)
            w.appendVarint(UInt64(self.values.count))
            for elem in self.values {
                w.appendFloat64(elem)
            }
            w.backpatchLength2(at: lenPos)
        }
    }

    @inlinable
    public mutating func mergeOmniBuf(from data: UnsafeBufferPointer<UInt8>, depth: Int, budget: inout DecodeBudget) throws {
        guard depth <= budget.maxDepth else {
            throw OmniBufError.depthLimitExceeded(depth)
        }
        var r = OmniBufReader(data)
        while !r.isAtEnd {
            let (fnum, wt) = try r.readTag()
            switch fnum {
            case 0:
                guard wt == WireType.wireSubMsg else {
                    throw OmniBufError.parse("Field #0 must have WireSubMsg (12), got \(wt)")
                }
                let slice = try r.readLenSlice()
                try SchemaMeta.validateSlice(slice, depth: depth &+ 1, budget: &budget)
            case 1:
                guard wt == WireType.wireString else {
                    try r.validateValue(wireType: wt, inCollection: false, depth: depth, maxDepth: budget.maxDepth)
                    continue
                }
                self.source = try r.readString(budget: &budget)
            case 2:
                guard wt == WireType.wireSint else {
                    try r.validateValue(wireType: wt, inCollection: false, depth: depth, maxDepth: budget.maxDepth)
                    continue
                }
                self.ts = try r.readSint64()
            case 3:
                guard wt == WireType.wireArray else {
                    try r.validateValue(wireType: wt, inCollection: false, depth: depth, maxDepth: budget.maxDepth)
                    continue
                }
                let arrDepth = depth &+ 1
                guard arrDepth <= budget.maxDepth else { throw OmniBufError.depthLimitExceeded(arrDepth) }
                let body = try r.readLenSlice(minLen: 2)
                let (elemWT, count, er0) = try OmniBufReader.parseArrayBody(body)
                guard elemWT == WireType.wireString else {
                    throw OmniBufError.parse("field 3 array element type mismatch")
                }
                try budget.addElements(count)
                try budget.addAlloc(count: count, elementBytes: max(MemoryLayout<String>.stride, 1))
                let (newCap, capOverflow) = self.tags.count.addingReportingOverflow(count)
                if capOverflow { throw OmniBufError.allocationLimitExceeded("array capacity overflow") }
                var er = er0
                self.tags.reserveCapacity(newCap)
                for _ in 0..<count {
                    let elem = try er.readString(budget: &budget)
                    self.tags.append(elem)
                }
                guard er.isAtEnd else { throw OmniBufError.parse("WireArray trailing bytes") }
            case 4:
                guard wt == WireType.wireArray else {
                    try r.validateValue(wireType: wt, inCollection: false, depth: depth, maxDepth: budget.maxDepth)
                    continue
                }
                let arrDepth = depth &+ 1
                guard arrDepth <= budget.maxDepth else { throw OmniBufError.depthLimitExceeded(arrDepth) }
                let body = try r.readLenSlice(minLen: 2)
                let (elemWT, count, er0) = try OmniBufReader.parseArrayBody(body)
                guard elemWT == WireType.wireFloat64 else {
                    throw OmniBufError.parse("field 4 array element type mismatch")
                }
                try budget.addElements(count)
                try budget.addAlloc(count: count, elementBytes: max(MemoryLayout<Double>.stride, 1))
                let (newCap, capOverflow) = self.values.count.addingReportingOverflow(count)
                if capOverflow { throw OmniBufError.allocationLimitExceeded("array capacity overflow") }
                var er = er0
                self.values.reserveCapacity(newCap)
                for _ in 0..<count {
                    let elem = try er.readFloat64()
                    self.values.append(elem)
                }
                guard er.isAtEnd else { throw OmniBufError.parse("WireArray trailing bytes") }
            default:
                try r.validateValue(wireType: wt, inCollection: false, depth: depth, maxDepth: budget.maxDepth)
            }
        }
    }

    public static var omniBufSchemaMeta: SchemaMeta {
        var visited: Set<String> = []
        return buildOmniBufSchemaMeta(visited: &visited)
    }

    public static func buildOmniBufSchemaMeta(visited: inout Set<String>) -> SchemaMeta {
        var fields: [UInt32: String] = [:]
        let children: [UInt32: SchemaMeta] = [:]
        fields[1] = "source"
        fields[2] = "ts"
        fields[3] = "tags"
        fields[4] = "values"
        return SchemaMeta(typeName: "Telemetry", fields: fields, children: children)
    }
}

